func folderRoleLabel(role string) string {
	switch role {
	case "sent":
		return "Sent"
	case "drafts":
		return "Drafts"
	case "trash":
		return "Trash"
	case "junk":
		return "Spam"
	case "archive":
		return "Archive"
	}
	return role
}

